"""Small public-API fixture for the attribution helper contract."""

RULES = (
    ("co-authored-by:", "ai-trailer"),
    ("generated with", "ai-footer"),
    ("<!-- generated by", "ai-footer"),
    ("author:", "ai-header"),
)


def classify(line):
    lowered = line.lstrip("\ufeff").lower().strip()
    if lowered.startswith("#"):
        lowered = lowered[1:].lstrip()
    for prefix, rule in RULES:
        if lowered.startswith(prefix) and any(
            name in lowered for name in ("chatgpt", "codex", "copilot", "claude")
        ):
            return rule
    return None


def findings(text, source="supplied text", numbers=None):
    lines = text.splitlines()
    selected = range(1, len(lines) + 1) if numbers is None else numbers
    return [
        (source, number, rule)
        for number in selected
        if 1 <= number <= len(lines)
        if (rule := classify(lines[number - 1])) is not None
    ]
